#!/usr/bin/env python3
from ta_emss import ta_emss
import time

CELL_ID_START = 5

if __name__ == "__main__":

    emss1 = ta_emss()
    emss1.setup_emss(user='vcu1', bts_ip='192.168.100.129', oam_ip='192.168.100.1/24', alias='cu1')

    # --- SETUP XTERM PARAMS ---
    print("Setting up...")
    emss1.xterm_setup(
        # --- F1AP PARAMS ---
        bts_f1ap_ip_addr="172.16.1.101",
        vdusim_ip_addr_begin="10.0.1.151",
        vdusim_ip_addr_end="10.0.1.160",
        vdusim_ip_addr_mask=24,
        vdusim_eth_if="eth3",
        init_vdu_gnb_du_id=2,
        init_vdu_frequency_band=85,
        init_vdu_num_cells=16,
        init_vdu_cell_id_begin=CELL_ID_START,
        init_vdu_ul_arfcn=139800,
        init_vdu_dl_arfcn=145800,
        init_vdu_tac=280,
        init_vdu_mcc="311",
        init_vdu_mnc="489",
        init_vdu_cell_dep_type='SA',
        # --- NGAP PARAMS ---
        amf_ip_addr="10.0.11.27",
        amf_mcc="311",
        amf_mnc="489",
        amf_eth_if="eth3",
        amf_ip_addr_mask="24",
        # --- XTERM OPTIONS ---
        verbose=True,
        debug=False
    )

    # --- CONFIGURE AMF MOCS ---
    amf_params = emss1.xterm_get("AMF")
    emss1.configure_bts({'MOC': 'SERVEDAMF', 'ID': amf_params['AMF_SET_ID'],
                         'amfIPAddress': amf_params['AMF_IP_ADDR']},
                        skip_np=False)
    time.sleep(5)

    # --- START NGAP SIMULATION ---
    print("Starting NGAP...")
    emss1.xterm_start(ngap=True)
    time.sleep(5)

    # --- CONFIGURE F1AP MOCS ---
    configure_mocs_command = []
    cell_id_start = CELL_ID_START
    dl_arfcn = emss1.xterm_get("vdus")[0]['DL_ARFCN']
    ul_arfcn = emss1.xterm_get("vdus")[0]['UL_ARFCN']

    for vdu in emss1.xterm_get("vdus"):
        vdu['DL_ARFCN'] = dl_arfcn
        vdu['UL_ARFCN'] = ul_arfcn
        du_id = vdu['GNB_DU_ID']
        cell_group_list = []
        for cell in vdu['SERVED_CELLS']:
            configure_mocs_command.append({'MOC': 'NRCELL', 'ID': str(cell_id_start),
                                           'a1MeashoEnabledSA': 'rsrp',
                                           'a1MeashoSsbRsrpSA': [{'a1HysteresishoSsbRsrpSA': 0,
                                                                  'a1ThresholdhoSsbRsrpSA': 60,
                                                                  'a1TimeToTriggerhoSsbRsrpSA': 'ms480'
                                                                  }],
                                           'a2MeashoEnabledSA': 'rsrp',
                                           'a2MeashoSsbRsrpSA': [{'a2HysteresishoSsbRsrpSA': '0',
                                                                  'a2ThresholdhoSsbRsrpSA': '34',
                                                                  'a2TimeToTriggerhoSsbRsrpSA': 'ms480'
                                                                  }],
                                           'cellReselectionPriority': '0',
                                           'cellDepType': vdu['CELL_DEP_TYPE'],
                                           'filterCoeffSsbRsrp': 'fc4',
                                           'filterCoeffSsbRsrq': 'fc4',
                                           'nrSysInfoProfileDN': 'MRBTS-1/NRBTS-1/NRSYSINFO_PROFILE-1',
                                           'trackingAreaDN': 'MRBTS-1/NRBTS-1/TRACKINGAREA-1',
                                           'freqBandIndicatorNR': vdu['FREQUENCY_BAND'],
                                           'lcrId': str(cell_id_start),
                                           'physCellId': cell['PCI'],
                                           'allowUnsuppBcOrBcs': ['accept unknown band combinations'],
                                           'chBw': '50MHz',
                                           'drxProfileNrAnr': [{'drxControl': 'any', 'nrDrxDN': 'MRBTS-1/NRBTS-1/NRDRX-3'}],
                                           'rlfPsccTrigThresholdRsrp': '42',
                                           'a1MeashoEnabled': 'none',
                                           'a2MeashoEnabled': 'none',
                                           'cellTechnology': 'FDD',
                                           'ssPbchBlockPower': '10',
                                           'actDataForwardingForVoNr': 'deactivated',
                                           })
            configure_mocs_command.append({'MOC': 'NRCELL_FDD', 'ID': f'{cell_id_start}-1',
                                           'chBwDl': '5MHz',
                                           'chBwUl': '5MHz',
                                           'nrarfcnDl': dl_arfcn,
                                           'nrarfcnUl': ul_arfcn
                                           })
            configure_mocs_command.append({'MOC': 'NRCELLGRP', 'ID': str(cell_id_start),
                                           'scs': '15 KHz',
                                           'nrCellList': [cell_id_start]
                                           })
            cell_group_list.append(cell_id_start)
            cell_id_start += 1

        configure_mocs_command.append({'MOC': 'NRDU', 'ID': du_id,
                                       'actConnectedModeMobilityCA': 'true',
                                       'actInterNumerologyCa': 'true',
                                       'carrierAggregationSupportList': ['ca_Fr1Tdd_Any_Sa', 'ca_Fr1Tdd_Fdd_Sa', 'ca_Fr1Tdd_Sa'],
                                       'flexibleCAMode': 'ConfigurationIndependent',
                                       'gNbDuId': du_id,
                                       'gNbDuName': f'VDU_{du_id}',
                                       'refNrCellGroup': cell_group_list,
                                       'remoteDuIpAddr': vdu['IP_ADDR']},
                                      )
        dl_arfcn += 20
        ul_arfcn += 20
    emss1.configure_bts(configure_mocs_command, skip_np=False)
    time.sleep(15)

    # --- START F1AP SIMULATION ---
    print("Starting F1AP...")
    emss1.xterm_start(f1ap=True)

    # --- BREAK SIMULATION ---
    while (k := input("Press 'q' to stop...")) != 'q':
        pass

    # --- DELETE PREVIOUSLY ADDED MOCS ---
    print("Deleting previously added SERVEDAMF MOC")
    emss1.configure_bts({'DEL': 'SERVEDAMF', 'ID': amf_params['AMF_SET_ID']})

    print("Deleting previously added NRDU, NRCELL, NRCELLGRP moc")
    delete_moc_command = []
    number_of_vdus = len(emss1.xterm_get("vdus"))
    number_of_cell_per_vdu = len(emss1.xterm_get("vdus")[0]['SERVED_CELLS'])

    for vdu in emss1.xterm_get("vdus"):
        delete_moc_command.append({'DEL': 'NRDU', 'ID': vdu['GNB_DU_ID']})
    for moc_id in range(CELL_ID_START, CELL_ID_START + number_of_vdus * number_of_cell_per_vdu):
        delete_moc_command.append({'DEL': 'NRCELLGRP', 'ID': moc_id})
        delete_moc_command.append({'DEL': 'NRCELL', 'ID': moc_id})
    emss1.configure_bts(delete_moc_command)

    # --- STOP XTERM ---
    print("Stopping xterm")
    emss1.xterm_teardown()
